os.makedirs(OUT, exist_ok=True)
for name, rows in [('mel_sel_labels.csv', MEL), ('win_sel_labels.csv', WIN)]:
    # validate: addresses unique, sorted
    addrs=[r[0] for r in rows]
    assert len(addrs)==len(set(addrs)), name
    with open(os.path.join(OUT,name),'w',newline='') as f:
        w=csv.writer(f)
        w.writerow(['address','name','kind','notes'])
        w.writerows(rows)
    print(name, len(rows), 'labels')
